@prefix ns1: <https://ada.astromat.org/metadata/> .
@prefix schema1: <http://schema.org/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ a <cdi:Activity>,
                        schema1:Action,
                        schema1:HowToStep ;
                    schema1:name "Data processing" ;
                    schema1:position 1 ;
                    ns1:detectionLimitMethod "no value available: unnamed property" ] ;
            sh:resultMessage "Less than 1 values on [ ada:detectionLimitMethod Literal(\"no value available: unnamed property\") ; rdf:type <cdi:Activity>, schema1:Action, schema1:HowToStep ; schema1:name Literal(\"Data processing\") ; schema1:position Literal(\"1\", datatype=xsd:integer) ]->schema1:target" ;
            sh:resultPath schema1:target ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:class schema1:EntryPoint ;
                    sh:minCount 1 ;
                    sh:path schema1:target ;
                    sh:property [ sh:datatype xsd:string ;
                            sh:message "A web service distribution must include a URL; the CDIF schema allows URL Templates" ;
                            sh:minCount 1 ;
                            sh:path schema1:urlTemplate ],
                        [ sh:datatype xsd:string ;
                            sh:path schema1:contentType ],
                        [ sh:datatype xsd:string ;
                            sh:path schema1:httpMethod ] ] ] .

